def halloween_update(CharClass):
    def wrapper(*args, **kwargs):
        # instantiate the Character
        char = CharClass(*args, **kwargs)

        costume = char.inventory["costume"]
        if costume:
            # update the costume
            char.inventory["costume"] = f"spooky {costume}"
        return char
    return wrapper

